syntax:
`typedef existing_type AliasName;
// or in modern C++
using AliasName = existing_type;`

code_example:
#include <map>
#include <string>
using StringFloatMap = std::map<std::string, float>;
int main() {
    StringFloatMap coll;
    coll["VAT"] = 0.15f;
    coll["Pi"] = 3.1415f;
    coll["an arbitrary number"] = 4983.223f;
    coll["Null"] = 0.0f;
    return 0;
}
